<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { Network, BookOpenText, GitBranch, RefreshCw, Download, Search, X, ArrowRight, Code2, Layers, FileText } from 'lucide-vue-next'
import PageShell from '@/components/PageShell.vue'
import KnowledgeGraphCanvas from '@/components/KnowledgeGraphCanvas.vue'
import { knowledgeGraphApi, documentsApi } from '@/api'
import { useUiStore } from '@/stores/ui'
const ui = useUiStore()
const graph = ref({ wiki: { nodes: [], edges: [], issues: [] }, semantic: { nodes: [], edges: [], issues: [] }, communities: [], build: { status: 'empty' } })
const loading = ref(false), building = ref(false), search = ref(''), question = ref(''), querying = ref(false), result = ref(null)
const selected = ref(null), sourcePreview = ref(null)
let timer, active = true, lastIdleRefresh = 0
const running = computed(() => ['queued','building'].includes(graph.value.build.status))
const nodeNames = computed(() => Object.fromEntries([...graph.value.wiki.nodes,...graph.value.semantic.nodes].map(n => [n.id,n.name])))
const stats = computed(() => [
  {label:'Wiki页面',value:graph.value.wiki.nodes.filter(n=>!n.unresolved).length,icon:BookOpenText},
  {label:'页面链接',value:graph.value.wiki.edges.length,icon:GitBranch},
  {label:'实体与概念',value:graph.value.semantic.nodes.length,icon:Network},
  {label:'语义关系',value:graph.value.semantic.edges.length,icon:ArrowRight},
  {label:'主题社区',value:graph.value.communities.length,icon:Layers},
])
function filtered(kind) {
  const data=graph.value[kind], term=search.value.trim().toLowerCase()
  if(!term)return data
  const ids=new Set(data.nodes.filter(n=>[n.name,n.type,...(n.aliases||[])].join(' ').toLowerCase().includes(term)).map(n=>n.id))
  for(const edge of data.edges.filter(e=>e.predicate?.toLowerCase().includes(term))){ids.add(edge.source);ids.add(edge.target)}
  const edges=data.edges.filter(e=>ids.has(e.source)||ids.has(e.target))
  const expanded=new Set([...ids,...edges.flatMap(e=>[e.source,e.target])])
  return {nodes:data.nodes.filter(n=>expanded.has(n.id)),edges}
}
const wikiGraph=computed(()=>filtered('wiki')), semanticGraph=computed(()=>filtered('semantic'))
const columns=computed(()=>Object.keys(result.value?.rows?.[0]||{}))
const selectionTitle=computed(()=>!selected.value?'':selected.value.kind==='community'?selected.value.item.title:selected.value.kind==='node'?selected.value.item.name:`${nodeNames.value[selected.value.item.source]} → ${nodeNames.value[selected.value.item.target]}`)
function selectCommunity(group){selected.value={kind:'community',item:{...group,evidence:graph.value.semantic.edges.filter(e=>group.relationIds.includes(e.id)).flatMap(e=>e.evidence)}}}
const neighbors=computed(()=>selected.value?.kind==='node'?[...graph.value.wiki.edges,...graph.value.semantic.edges].filter(e=>e.source===selected.value.item.id||e.target===selected.value.item.id):[])
async function refresh(silent=false){if(loading.value)return;loading.value=true;try{const data=await knowledgeGraphApi.get();if(active)graph.value=data}catch(error){if(!silent)ui.toast(error?.message||'无法读取图谱','error')}finally{loading.value=false}}
async function build(){if(building.value||running.value)return;building.value=true;try{graph.value=await knowledgeGraphApi.build();ui.toast('已开始后台构建，切换页面后仍会继续')}catch(error){ui.toast(error?.message||'无法构建图谱','error')}finally{building.value=false}}
async function query(){if(!question.value.trim()||querying.value)return;querying.value=true;result.value=null;try{result.value=await knowledgeGraphApi.query(question.value.trim())}catch(error){ui.toast(error?.message||'图谱查询失败','error')}finally{querying.value=false}}
async function exportGraph(){try{const data=await knowledgeGraphApi.export();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='personal-knowledge-graph.json';link.click();URL.revokeObjectURL(url)}catch(error){ui.toast(error?.message||'导出失败','error')}}
async function previewSource(proof){try{sourcePreview.value={...(await documentsApi.get(proof.documentId)),proof}}catch(error){ui.toast(error?.message||'原始资料不可用','error')}}
onMounted(async()=>{await refresh();if(active)timer=window.setInterval(()=>{if(running.value||Date.now()-lastIdleRefresh>6000){lastIdleRefresh=Date.now();void refresh(true)}},1500)})
onUnmounted(()=>{active=false;window.clearInterval(timer)})
</script>

<template>
  <PageShell title="知识可视化" subtitle="从Wiki页面链接到实体关系，探索知识之间的联系与原文依据。">
    <template #actions><button class="kg-button secondary" @click="exportGraph"><Download :size="16"/>导出JSON</button><button class="kg-button" :disabled="building||running" @click="build"><RefreshCw :size="16" :class="{spin:building||running}"/>构建 / 更新图谱</button></template>
    <div class="kg-workspace">
      <div class="kg-stats"><article v-for="stat in stats" :key="stat.label"><component :is="stat.icon" :size="19"/><div><small>{{stat.label}}</small><strong>{{stat.value}}</strong></div></article></div>
      <div v-if="running" class="kg-status"><RefreshCw class="spin" :size="20"/><div><strong>图谱正在后台构建</strong><p>{{graph.build.stage}} · {{graph.build.completed}} / {{graph.build.total||'—'}} 页</p></div><span>可继续使用已有图谱</span></div>
      <div v-else-if="graph.build.error" class="kg-notice">{{graph.build.error}}</div>
      <div v-else-if="graph.stale&&graph.recordCount" class="kg-notice">Wiki已更新，请构建图谱。首次构建后，Wiki变化会自动触发增量更新。</div>
      <section class="kg-query-panel"><div class="kg-query-heading"><Code2 :size="18"/><strong>用自然语言查询图谱</strong><small>仅查询当前账号的有效知识图谱</small></div><form @submit.prevent="query"><input v-model="question" placeholder="例如：哪些概念基于Transformer？它们之间有什么关系？" maxlength="8000"/><button class="kg-button" :disabled="querying||!question.trim()"><RefreshCw v-if="querying" class="spin" :size="16"/><Search v-else :size="16"/>图谱查询</button></form>
        <div class="kg-query-examples"><button v-for="example in ['知识库中有哪些主题？','哪些概念之间存在依赖关系？','当前图谱有多少实体和关系？']" :key="example" @click="question=example;query()">{{example}}</button></div>
        <div v-if="result" class="kg-query-result"><p v-if="result.warning" class="kg-notice">{{result.warning}}</p><p>找到 {{result.hits?.length||0}} 个原文片段 · 扩展 {{Object.keys(result.pagePaths||{}).length}} 个Wiki页面 · {{result.communities?.length||0}} 个相关社区</p><details v-if="result.sql" open><summary>{{result.sqlStatus==='executed'?'已执行的只读SQL与结果':'未执行的生成SQL（已回退）'}}</summary><pre>{{result.sql}}</pre><small>绑定参数：{{JSON.stringify(result.params)}}</small><div class="kg-scroll"><table v-if="result.rows?.length"><thead><tr><th v-for="column in columns" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="(row,i) in result.rows" :key="i"><td v-for="column in columns" :key="column">{{row[column]}}</td></tr></tbody></table><p v-else>SQL未命中记录，仍会尝试关键词与图关系扩展。</p></div></details><div class="kg-query-evidence"><button v-for="(hit,i) in result.hits" :key="i" @click="previewSource({...hit,quote:hit.text})"><FileText :size="15"/><span>{{hit.graphOverview||'原文依据'}}</span><small>查看来源</small></button></div></div>
      </section>
      <div class="kg-search"><Search :size="17"/><input v-model="search" placeholder="筛选页面、实体、别名或关系类型"/><button v-if="search" aria-label="清空筛选" @click="search=''"><X :size="15"/></button><button aria-label="刷新图谱" @click="refresh"><RefreshCw :size="17" :class="{spin:loading}"/></button></div>
      <div class="kg-graph-grid">
        <section class="kg-panel"><header><div><span class="kg-kicker">WIKI LINK GRAPH</span><h2><BookOpenText :size="21"/>Wiki页面图</h2><p>出链与反向链接，用于知识导航和跨文档扩展。</p></div><span class="kg-count">{{graph.wiki.edges.length}} 条链接</span></header><KnowledgeGraphCanvas :nodes="wikiGraph.nodes" :edges="wikiGraph.edges" :selected-id="selected?.item.id" @select="selected=$event"><template #empty>上传资料并编译Wiki后，页面和 <code>[[wikilink]]</code> 会显示在这里。<br/>未解析目标会以虚线显示。</template></KnowledgeGraphCanvas><details v-if="graph.wiki.issues?.length" class="kg-lint"><summary>{{graph.wiki.issues.length}} 个链接需要处理</summary><p v-for="(issue,i) in graph.wiki.issues" :key="i">{{nodeNames[issue.documentId]}} → {{issue.target}} · {{issue.kind==='ambiguous'?'同名目标，请明确页面名称':'目标页面尚不存在'}}</p></details></section>
        <section class="kg-panel"><header><div><span class="kg-kicker">SEMANTIC KNOWLEDGE GRAPH</span><h2><Network :size="21"/>语义知识图谱</h2><p>实体—关系—实体，每条边保留Wiki段落与原文引用。</p></div><span class="kg-count">{{graph.semantic.edges.length}} 条关系</span></header><KnowledgeGraphCanvas :nodes="semanticGraph.nodes" :edges="semanticGraph.edges" :selected-id="selected?.item.id" @select="selected=$event"><template #empty>点击“构建 / 更新图谱”，从Wiki原文依据中抽取实体与关系。<br/>这里只展示真实抽取结果。</template></KnowledgeGraphCanvas><div class="kg-legend"><span v-for="type in ['人物','组织','产品','概念','事件','地点']" :key="type">{{type}}</span></div><p v-if="graph.semantic.issues?.length" class="kg-lint">{{graph.semantic.issues.length}} 条候选关系未通过原文校验，未加入图谱。</p></section>
      </div>
      <section v-if="selected" class="kg-panel"><header><div><span class="kg-kicker">PROVENANCE & CONNECTIONS</span><h2>{{selectionTitle}}</h2></div><button aria-label="关闭详情" @click="selected=null"><X :size="20"/></button></header><div class="kg-selection-body"><p v-if="selected.kind==='node'">{{selected.item.type}} · {{selected.item.qualifier||'未设置限定信息'}}<span v-if="selected.item.aliases?.length"> · 别名：{{selected.item.aliases.join('、')}}</span></p><p v-else-if="selected.kind==='edge'">关系：{{selected.item.predicate}}<span v-if="selected.item.confidence"> · 模型置信度 {{Math.round(selected.item.confidence*100)}}%</span><span v-if="selected.item.paragraph"> · 来源段落 {{selected.item.paragraph}}</span></p><p v-if="selected.kind==='community'">此社区包含 {{selected.item.entityIds.length}} 个实体、{{selected.item.relationIds.length}} 条关系。下方可核对原始依据。</p><div class="kg-neighbors"><button v-for="edge in neighbors.slice(0,30)" :key="edge.id" @click="selected={kind:'edge',item:edge}">{{nodeNames[edge.source]}} <b>{{edge.predicate}}</b> {{nodeNames[edge.target]}}</button></div><div class="kg-evidence-list"><article v-for="(proof,i) in selected.item.evidence||[]" :key="i"><small>{{nodeNames[proof.wikiId]||proof.wikiId}} · {{proof.paragraphId}} · 第{{proof.page}}页 · [{{proof.sourceId}}]</small><blockquote>{{proof.quote}}</blockquote><button class="kg-button secondary" @click="previewSource(proof)"><FileText :size="15"/>查看原始资料</button></article></div><p v-if="selected.kind==='edge'&&!selected.item.evidence">页面链接表示导航关联，不自动等同于语义事实关系。</p></div></section>
      <section class="kg-panel"><header><div><span class="kg-kicker">TOPIC COMMUNITIES</span><h2><Layers :size="20"/>主题社区</h2><p>按语义关系划分主题，用于跨文档探索和全局摘要召回。</p></div></header><div v-if="graph.communities.length" class="kg-community-grid"><article v-for="group in graph.communities" :key="group.id"><h3>{{group.title}}</h3><small>{{group.entityIds.length}} 个实体 · {{group.relationIds.length}} 条关系 · {{group.summaryMethod==='llm'?'模型摘要':'关系速览'}}</small><p class="kg-community-summary">{{group.summary||'暂无摘要'}}</p><button class="kg-button secondary" @click="search=group.title.split(' · ')[0];selected=null">探索主题<ArrowRight :size="14"/></button><button class="kg-button secondary" @click="selectCommunity(group)">查看摘要依据</button></article></div><p v-else class="kg-empty">构建语义关系后自动生成主题社区。</p></section>
      <section class="kg-panel"><header><div><span class="kg-kicker">TRACEABLE TRIPLES</span><h2>实体关系明细</h2></div><span class="kg-count">筛选后 {{semanticGraph.edges.length}} 条</span></header><div class="kg-scroll"><table v-if="semanticGraph.edges.length"><thead><tr><th>实体</th><th>关系</th><th>实体</th><th>原文来源</th><th>依据</th></tr></thead><tbody><tr v-for="edge in semanticGraph.edges.slice(0,100)" :key="edge.id"><td>{{nodeNames[edge.source]}}</td><td><span class="kg-count">{{edge.predicate}}</span></td><td>{{nodeNames[edge.target]}}</td><td>{{edge.evidence.length}} 处引用</td><td><button class="kg-table-link" @click="selected={kind:'edge',item:edge}">查看原文<ArrowRight :size="14"/></button></td></tr></tbody></table><p v-else class="kg-empty">暂无符合条件的语义关系。</p><p v-if="semanticGraph.edges.length>100" class="kg-empty">显示前100条，请用筛选缩小范围。</p></div></section>
      <Teleport to="body"><div v-if="sourcePreview" class="kg-modal-mask" @click.self="sourcePreview=null"><section class="kg-source-modal"><header><div><small>原文来源</small><h2>{{sourcePreview.title}}</h2></div><button aria-label="关闭来源" @click="sourcePreview=null"><X :size="22"/></button></header><blockquote>{{sourcePreview.proof.quote}}</blockquote><small v-if="sourcePreview.proof.sourceId">引用 {{sourcePreview.proof.sourceId}} · 第{{sourcePreview.proof.page}}页</small><div v-if="sourcePreview.chunks?.length"><article v-for="chunk in sourcePreview.chunks.filter(c=>!sourcePreview.proof.page||c.page===sourcePreview.proof.page)" :key="chunk.id"><small>{{chunk.section}} · 第{{chunk.page}}页</small><p>{{chunk.text}}</p></article></div><p v-else>该资料尚未向量化。上方为Wiki编译时保存的原文引用。</p><details v-if="sourcePreview.wikiMarkdown"><summary>对应Wiki正文</summary><pre>{{sourcePreview.wikiMarkdown}}</pre></details></section></div></Teleport>
    </div>
  </PageShell>
</template>

<style scoped>
.kg-workspace{display:grid;gap:20px}.kg-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.kg-stats article{display:flex;align-items:center;gap:13px;padding:18px;border:1px solid #e8def2;border-radius:16px;background:linear-gradient(130deg,#fff,#faf7ff);color:#8055ae}.kg-stats article div{display:grid;gap:6px}.kg-stats small{color:#907e9f;font-size:12px}.kg-stats strong{font-size:27px;color:#3b2555}.kg-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid #7130bd;border-radius:11px;background:#7130bd;color:#fff;padding:11px 16px;font-size:13px;font-weight:650;cursor:pointer;white-space:nowrap}.kg-button:hover:not(:disabled){background:#5e20a4}.kg-button.secondary{background:#f9f5ff;border-color:#e1d2f1;color:#76479d}.kg-button.secondary:hover{background:#eee2fc}.kg-button:disabled{opacity:.65;cursor:default}.kg-status{display:flex;align-items:center;gap:15px;padding:18px 22px;border:1px solid #d8bdf5;border-radius:15px;background:#f3eaff;color:#6526a4}.kg-status p{margin:6px 0 0;font-size:13px}.kg-status>span{margin-left:auto;font-size:12px}.kg-notice{padding:13px 17px;border:1px solid #e6daef;border-radius:12px;background:#fcf9ff;color:#8b719e;font-size:13px;line-height:1.7}
