.kg-search{display:flex;align-items:center;gap:10px;max-width:580px;border:1px solid #e5d8ef;border-radius:12px;padding:11px 14px;background:#fff;color:#a38ab9}.kg-search input{flex:1;min-width:0;border:0;outline:none;background:none;color:#654979;font-size:13px}.kg-search button,.kg-panel header>button,.kg-source-modal header>button{display:grid;place-items:center;border:0;background:none;color:#9478aa;cursor:pointer}.kg-graph-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.kg-panel header{display:flex;align-items:start;justify-content:space-between;gap:12px;padding:23px 24px 18px;border-bottom:1px solid #f0e8f7}.kg-kicker{font-size:10px;font-weight:700;color:#aa87c3;letter-spacing:1.5px}.kg-panel h2{display:flex;align-items:center;gap:9px;margin:8px 0;color:#46295f;font-size:19px}.kg-panel header p{color:#9b85ad;font-size:12px;line-height:1.8;margin:0}.kg-count{display:inline-flex;padding:5px 9px;border-radius:7px;color:#8c62aa;background:#f5eefb;font-size:11px;white-space:nowrap}.kg-lint{padding:13px 20px;color:#a07c8f;font-size:12px;background:#fffafb}.kg-lint p{margin:7px 0}.kg-legend{display:flex;gap:8px;flex-wrap:wrap;padding:0 20px 15px}.kg-legend span{font-size:11px;color:#9c88ad;padding:3px 8px;border:1px solid #e9e0f2;border-radius:7px}.kg-selection-body{padding:20px 24px;color:#816092;font-size:13px;line-height:1.9}.kg-neighbors{display:flex;flex-wrap:wrap;gap:8px}.kg-neighbors button{border:1px solid #e6d8f0;border-radius:9px;background:#fbf8ff;padding:9px 12px;color:#73528a;cursor:pointer}.kg-neighbors b{color:#9c7eae;font-weight:500;margin:0 8px}.kg-evidence-list{display:grid;gap:12px}.kg-evidence-list article{padding:16px;border:1px solid #e8dbf2;border-radius:12px;background:#fdfaff}.kg-evidence-list small{color:#a286b4}.kg-evidence-list blockquote,.kg-source-modal blockquote{margin:12px 0;padding:12px 16px;border-left:3px solid #b286d5;background:#f8f2fd;white-space:pre-wrap;color:#694d7e;line-height:1.9}
.kg-community-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;padding:20px}.kg-community-grid article{padding:17px;border:1px solid #e9dff3;border-radius:14px;background:linear-gradient(130deg,#fff,#fcf9ff)}.kg-community-grid h3{font-size:15px;color:#61417b;margin:0 0 7px}.kg-community-grid small{font-size:11px;color:#ad96bb}.kg-community-summary{white-space:pre-wrap;max-height:180px;overflow:auto;line-height:1.9;color:#897095;font-size:12px;margin:13px 0 16px}.kg-scroll{overflow:auto}.kg-scroll table{width:100%;border-collapse:collapse;text-align:left;font-size:12px;color:#7f6692}.kg-scroll th{background:#faf6fe;color:#a08aaa;padding:13px 20px;white-space:nowrap}.kg-scroll td{padding:13px 20px;border-top:1px solid #f0e8f6;max-width:500px;overflow-wrap:anywhere}.kg-table-link{display:inline-flex;align-items:center;gap:6px;background:none;border:0;color:#8148af;cursor:pointer}.kg-empty{padding:24px;text-align:center;color:#b09bbc;font-size:13px}.kg-modal-mask{position:fixed;inset:0;z-index:10000;background:#26163666;backdrop-filter:blur(5px);display:grid;place-items:center;padding:30px}.kg-source-modal{width:min(920px,100%);max-height:85vh;overflow:auto;border-radius:20px;background:#fff;padding:28px;color:#785f8a;font-size:13px;line-height:1.9}.kg-source-modal header{display:flex;justify-content:space-between;align-items:start;gap:20px}.kg-source-modal h2{margin:5px 0;font-size:21px;color:#4a2e61}.kg-source-modal article{border-top:1px solid #eee4f6;padding-top:14px;margin-top:14px}.spin{animation:kg-spin .9s linear infinite}@keyframes kg-spin{to{transform:rotate(360deg)}}@media(max-width:1100px){.kg-graph-grid{grid-template-columns:1fr}.kg-community-grid{grid-template-columns:1fr 1fr}.kg-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.kg-stats{grid-template-columns:repeat(2,1fr)}.kg-query-panel form{flex-direction:column}.kg-community-grid{grid-template-columns:1fr}.kg-query-heading small,.kg-status>span{display:none}.kg-panel header{padding:18px}.kg-modal-mask{padding:12px}}
</style>
